(()=>{'use strict';let busy=false;function update(){busy=false;const row=document.querySelector('#main-content .pati-ig-profile .pati-own-profile-actions');if(!row)return;for(const b of row.querySelectorAll(':scope > button')){if(/^(profili\s*)?düzenle$/i.test((b.textContent||'').trim())){b.classList.add('buchee-edit-compact');if(b.textContent.trim()!=='Düzenle')b.textContent='Düzenle'}}}function schedule(){if(!busy){busy=true;requestAnimationFrame(update)}}new MutationObserver(schedule).observe(document.getElementById('main-content')||document.body,{subtree:true,childList:true});document.addEventListener('DOMContentLoaded',schedule);schedule()})();